CREATE TYPE "ReactionType" AS ENUM ('LIKE', 'DISLIKE');
CREATE TYPE "FollowType" AS ENUM ('PUBLICATION', 'AUTHOR', 'CATEGORY');
CREATE TYPE "NotificationChannel" AS ENUM ('EMAIL', 'PUSH', 'BOTH');
CREATE TYPE "NotificationAudience" AS ENUM ('ALL', 'BREAKING', 'CATEGORY', 'AUTHOR');
CREATE TYPE "NotificationStatus" AS ENUM ('PENDING', 'PROCESSING', 'SENT', 'PARTIAL', 'FAILED');
CREATE TYPE "DeliveryStatus" AS ENUM ('PENDING', 'PROCESSING', 'SENT', 'FAILED', 'SKIPPED');

ALTER TABLE "Comment" ADD COLUMN "readerId" TEXT, ADD COLUMN "parentId" TEXT, ADD COLUMN "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;

CREATE TABLE "Reader" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"name" TEXT NOT NULL,"verifiedAt" TIMESTAMP(3),"active" BOOLEAN NOT NULL DEFAULT true,"verificationToken" TEXT,"resetToken" TEXT,"resetExpiresAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Reader_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ArticleReaction" ("id" TEXT NOT NULL,"readerId" TEXT NOT NULL,"articleId" TEXT NOT NULL,"type" "ReactionType" NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ArticleReaction_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CommentReaction" ("id" TEXT NOT NULL,"readerId" TEXT NOT NULL,"commentId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CommentReaction_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CommentReport" ("id" TEXT NOT NULL,"readerId" TEXT NOT NULL,"commentId" TEXT NOT NULL,"reason" TEXT NOT NULL,"resolved" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CommentReport_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Follow" ("id" TEXT NOT NULL,"readerId" TEXT NOT NULL,"type" "FollowType" NOT NULL,"targetKey" TEXT NOT NULL,"authorId" TEXT,"categoryId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Follow_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SavedArticle" ("id" TEXT NOT NULL,"readerId" TEXT NOT NULL,"articleId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SavedArticle_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PushSubscription" ("id" TEXT NOT NULL,"readerId" TEXT,"endpoint" TEXT NOT NULL,"p256dh" TEXT NOT NULL,"auth" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PushSubscription_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NotificationPreference" ("id" TEXT NOT NULL,"readerId" TEXT NOT NULL,"browserEnabled" BOOLEAN NOT NULL DEFAULT false,"emailEnabled" BOOLEAN NOT NULL DEFAULT false,"breakingNews" BOOLEAN NOT NULL DEFAULT true,"allNews" BOOLEAN NOT NULL DEFAULT false,"followedCategories" BOOLEAN NOT NULL DEFAULT true,"followedAuthors" BOOLEAN NOT NULL DEFAULT true,"newsletter" BOOLEAN NOT NULL DEFAULT false,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NotificationPreference_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Notification" ("id" TEXT NOT NULL,"title" TEXT NOT NULL,"message" TEXT NOT NULL,"imageUrl" TEXT,"destinationUrl" TEXT NOT NULL,"audience" "NotificationAudience" NOT NULL,"channel" "NotificationChannel" NOT NULL,"categoryId" TEXT,"authorId" TEXT,"articleId" TEXT,"scheduledAt" TIMESTAMP(3),"status" "NotificationStatus" NOT NULL DEFAULT 'PENDING',"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Notification_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NotificationDelivery" ("id" TEXT NOT NULL,"notificationId" TEXT NOT NULL,"channel" "NotificationChannel" NOT NULL,"recipientKey" TEXT NOT NULL,"status" "DeliveryStatus" NOT NULL DEFAULT 'PENDING',"attempts" INTEGER NOT NULL DEFAULT 0,"lastError" TEXT,"sentAt" TIMESTAMP(3),"nextAttemptAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NotificationDelivery_pkey" PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "Reader_email_key" ON "Reader"("email"); CREATE UNIQUE INDEX "Reader_verificationToken_key" ON "Reader"("verificationToken"); CREATE UNIQUE INDEX "Reader_resetToken_key" ON "Reader"("resetToken"); CREATE INDEX "Reader_active_createdAt_idx" ON "Reader"("active","createdAt");
CREATE UNIQUE INDEX "ArticleReaction_readerId_articleId_key" ON "ArticleReaction"("readerId","articleId"); CREATE INDEX "ArticleReaction_articleId_type_idx" ON "ArticleReaction"("articleId","type");
CREATE UNIQUE INDEX "CommentReaction_readerId_commentId_key" ON "CommentReaction"("readerId","commentId"); CREATE INDEX "CommentReaction_commentId_idx" ON "CommentReaction"("commentId");
CREATE UNIQUE INDEX "CommentReport_readerId_commentId_key" ON "CommentReport"("readerId","commentId"); CREATE INDEX "CommentReport_resolved_createdAt_idx" ON "CommentReport"("resolved","createdAt");
CREATE UNIQUE INDEX "Follow_readerId_type_targetKey_key" ON "Follow"("readerId","type","targetKey"); CREATE INDEX "Follow_type_authorId_idx" ON "Follow"("type","authorId"); CREATE INDEX "Follow_type_categoryId_idx" ON "Follow"("type","categoryId");
CREATE UNIQUE INDEX "SavedArticle_readerId_articleId_key" ON "SavedArticle"("readerId","articleId"); CREATE INDEX "SavedArticle_articleId_idx" ON "SavedArticle"("articleId");
CREATE UNIQUE INDEX "PushSubscription_endpoint_key" ON "PushSubscription"("endpoint"); CREATE INDEX "PushSubscription_readerId_active_idx" ON "PushSubscription"("readerId","active");
CREATE UNIQUE INDEX "NotificationPreference_readerId_key" ON "NotificationPreference"("readerId"); CREATE INDEX "Notification_status_scheduledAt_idx" ON "Notification"("status","scheduledAt"); CREATE INDEX "Notification_audience_categoryId_authorId_idx" ON "Notification"("audience","categoryId","authorId");
CREATE UNIQUE INDEX "NotificationDelivery_notificationId_channel_recipientKey_key" ON "NotificationDelivery"("notificationId","channel","recipientKey"); CREATE INDEX "NotificationDelivery_status_nextAttemptAt_idx" ON "NotificationDelivery"("status","nextAttemptAt");

ALTER TABLE "Comment" ADD CONSTRAINT "Comment_readerId_fkey" FOREIGN KEY ("readerId") REFERENCES "Reader"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Comment" ADD CONSTRAINT "Comment_parentId_fkey" FOREIGN KEY ("parentId") REFERENCES "Comment"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ArticleReaction" ADD CONSTRAINT "ArticleReaction_readerId_fkey" FOREIGN KEY ("readerId") REFERENCES "Reader"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ArticleReaction" ADD CONSTRAINT "ArticleReaction_articleId_fkey" FOREIGN KEY ("articleId") REFERENCES "Article"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CommentReaction" ADD CONSTRAINT "CommentReaction_readerId_fkey" FOREIGN KEY ("readerId") REFERENCES "Reader"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CommentReaction" ADD CONSTRAINT "CommentReaction_commentId_fkey" FOREIGN KEY ("commentId") REFERENCES "Comment"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CommentReport" ADD CONSTRAINT "CommentReport_readerId_fkey" FOREIGN KEY ("readerId") REFERENCES "Reader"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CommentReport" ADD CONSTRAINT "CommentReport_commentId_fkey" FOREIGN KEY ("commentId") REFERENCES "Comment"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Follow" ADD CONSTRAINT "Follow_readerId_fkey" FOREIGN KEY ("readerId") REFERENCES "Reader"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Follow" ADD CONSTRAINT "Follow_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Follow" ADD CONSTRAINT "Follow_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SavedArticle" ADD CONSTRAINT "SavedArticle_readerId_fkey" FOREIGN KEY ("readerId") REFERENCES "Reader"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "SavedArticle" ADD CONSTRAINT "SavedArticle_articleId_fkey" FOREIGN KEY ("articleId") REFERENCES "Article"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PushSubscription" ADD CONSTRAINT "PushSubscription_readerId_fkey" FOREIGN KEY ("readerId") REFERENCES "Reader"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "NotificationPreference" ADD CONSTRAINT "NotificationPreference_readerId_fkey" FOREIGN KEY ("readerId") REFERENCES "Reader"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Notification" ADD CONSTRAINT "Notification_articleId_fkey" FOREIGN KEY ("articleId") REFERENCES "Article"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "NotificationDelivery" ADD CONSTRAINT "NotificationDelivery_notificationId_fkey" FOREIGN KEY ("notificationId") REFERENCES "Notification"("id") ON DELETE CASCADE ON UPDATE CASCADE;
